create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.KMR_PRUEFUNG_2 (
	AMX_SYSTEM_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'AMX-Quellsystem-ID zur Unterscheidung der verschiedenen AMX Systeme (1 = Core and 2 = Unternehmenssicherheit). Quellfeld amx_system.',
	PRUEFUNG_ID NUMBER(38,0) NOT NULL COMMENT 'Prüfungs-ID. Quellfeld auditing_id.',
	FEHLERVERDACHT_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Identifizierung fehlerhafter Prüfprogramme in der Quelle. \""Errechnetes\"" Hierarchielevel = 1 -> Bei späteren INCs soll sich Prüfprogramm anschauen, ob fachliche Vorgaben erfüllt sind. Quellfeld has_flawed_audit_program.',
	PRUEFUNG_NR VARCHAR(30) NOT NULL DEFAULT ' ' COMMENT 'Prüfungsnummer. Quellfeld auditing_a_number.',
	PRUEFUNG_BEZ VARCHAR(350) NOT NULL DEFAULT ' ' COMMENT 'Prüfungsname. Quellfeld auditing_name.',
	PRUEFUNG_KLASSE_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Prüfungsart / -klasse-ID. Quellfeld auditing_auditing_class_id.',
	PRUEFUNG_TYP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Prüfungstyp-ID, bspw. Ad hoc, Revisionsauftrag etc. Quellfeld auditing_auditing_type_id.',
	PRUEFUNG_STATUS_ID NUMBER(38,0) COMMENT 'Prüfungsstatus-ID. Quellfeld auditing_state.',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH.',
	STANDORT_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Standort-ID. Quellfeld auditing_location_id.',
	GEPR_OE_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Geprüfte Organisationseinheit-ID. Enthält die ID der Organisationseinheit (kmr_l_organisationseinheit.orga_einheit_id), die geprüft wurde. Muss nicht unbedingt für eine_2 Feststellung verantwortlich sein, weshalb die zuständige Stelle für eine_2 Maßnahme von hier abweichen kann. Quellfeld auditing_audited_org_unit_id.',
	LEIT_ABTEILUNG_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Leitende Abteilung-ID. Quellfeld auditing_leading_dep_id.',
	DAT_PRUEF_ZEITRAUM_VON DATE COMMENT 'Datum Prüfungsbeginn, \""Prüfungszeitraum von\"". Nicht zwingend das gleiche Datum wie dat_beginn_pruefung. Quellfeld auditing_start_date.',
	DAT_PRUEF_ZEITRAUM_BIS DATE COMMENT 'Datum Prüfungsende, \""Prüfungszeitraum bis\"". Nicht zwingend das gleiche Datum wie dat_ende_pruefung. Quellfeld auditing_end_date.',
	DAT_TERMIN_VEREINBART DATE COMMENT 'Datum Termin vereinbart. Quellfeld auditing_state_date_1.',
	DAT_VERSAND_ANKUENDIGUNG DATE COMMENT 'Datum Prüfungsankündigung verschickt. Quellfeld auditing_state_date_2.',
	DAT_BEGINN_PRUEFUNG DATE COMMENT 'Datum Prüfungsbeginn. Nicht zwingend das gleiche Datum wie dat_pruef_zeitraum_von. Quellfeld auditing_state_date_3.',
	DAT_ENDE_PRUEFUNG DATE COMMENT 'Datum Prüfungsende. Nicht zwingend das gleiche Datum wie dat_pruef_zeitraum_bis. Quellfeld auditing_state_date_4.',
	DAT_VERSAND_BERICHTSENTWURF DATE COMMENT 'Datum Berichtsentwurf versandt. Quellfeld auditing_state_date_5.',
	DAT_RUECKMELDUNG_BERICHTSENTWURF DATE COMMENT 'Datum Rückmeldung Berichtsentwurf. Quellfeld auditing_state_date_6.',
	DAT_VERSAND_BERICHT DATE COMMENT 'Datum Bericht versandt. Quellfeld auditing_state_date_7.',
	DAT_VERSAND_BERICHT_KORRIGIERT DATE COMMENT 'Datum Korrigierter Bericht versandt. Datum des Berichtsversandts, nachdem der Bericht nach dem ersten Versand zwischenzeitlich korrigiert wurde. Quellfeld auditing_state_date_8.',
	TAGESZEIT_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Tageszeit (früh, mittel, spät). Quellfeld auditing_reserve_sel_auditing_00_id.',
	PRUEFFELD_ID NUMBER(38,0) COMMENT 'Prüffeld-ID, Prüfungsebene. Rückbezug auf den Ursprung des Ergebnisses zu Analysezwecken der Prüfung, Prüfungprogramm oder Prüfergebnis. Quellfeld contains_pu_id_audit_level.',
	ERGEBNIS NUMBER(38,0) COMMENT 'Endergebnis, Prüfungsebene. Prüfungsergebnis, unabhängig von durchgeführtem Prüfprogramm. Quellfeld numeric_result_audit_level.',
	ERGEBNIS_BERECHNET NUMBER(38,0) COMMENT 'Ergebnis Prüfung (berechnet). Ergebnis auf Prüfungsebene, 1 oder 0, anhand von z.B. einer Quote zur Warenverfügbarkeit. Kann abweichen von ergebnis_manuell. Quellfeld contains_pu_computed_numeric_result_audit_level.',
	ERGEBNIS_MANUELL NUMBER(38,0) COMMENT 'Ergebnis Prüfung (manuell). Einschätzung vom Prüfer. Ergebnis auf Prüfungsebene, 1 oder 0. Kann abweichen vom berechneten Wert. Quellfeld contains_pu_manual_numeric_result_audit_level.',
	GEPR_PROZESS_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Geprüfter Prozess-ID. Quellfeld audit_universe_audited_process_id_audit_level.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	PRUEFUNG_BEREICH_ID NUMBER(38,0) COMMENT 'Zu berücksichtigende Bereiche / Code of area which should be considered / revisioned in a quick audit / \""Kurzcheck\"". For other audit types these codes are not applicable.',
	constraint PK_KMR_PRUEFUNG primary key (AMX_SYSTEM_ID, PRUEFUNG_ID)
)COMMENT='KMR - Delete / insert tansactional snapshot_2 of the current date minus 365 days. \n             \n             The data in the table contains results of all possible audit types. \n             This includes, for example, the data from the store audit (Filialrevision), topic (Area) and process audits and Audit checks by the Corporate Security department. \n             Newly, as of 01.08.24 the table contains quick checks (Kurzchecks) as well.\n             \n             The column pruefung_klasse_id shows what kind of audit each row represents.\n             \n             Source view v_dwh_kl_data_auditing.'
;
